#include "../../native/mobile-accountproof-host-v1/MobileAccountProofWireDATA.hpp"
#include <iostream>
#include <functional>
using namespace ynx::sdk::mobile::accountproof;
namespace w=ynx::sdk::mobile::accountproof::wire;
void ok(bool x){if(!x)throw std::runtime_error("PUBLIC_DATA_ASSERT");}
void denied(const std::function<void()>&f){bool n=false;try{f();}catch(const std::invalid_argument&){n=true;}ok(n);}
CommittedProofViewDATA sample(){CommittedProofViewDATA v;v.proof.chainID="PUBLIC-chain";v.proof.height=10;v.proof.appHash[0]=7;v.currentCheckpoint=v.proof;v.currentCheckpoint.height=12;v.currentCheckpoint.appHash[0]=9;v.historicalAccount.owner="0x1111111111111111111111111111111111111111";v.historicalAccount.nativeChainID=123;v.historicalAccount.committedHeight=10;v.historicalAccount.executionHeight=11;v.historicalAccount.ledgerNonce=3;v.historicalAccount.policyOriginal=Bytes{'{','"','v','"',':','"','1','"','}'};v.historicalAccount.committedAuthorizationStatus="active";v.historicalAccount.authorizationStatus="active";RegistrationDATA r;r.algorithmVersion="PUBLIC-DATA-only";r.owner=v.historicalAccount.owner;r.pkA.resize(2592);r.pkB.resize(64);r.revision=9007199254740993ULL;r.registeredAt=2;r.activeFrom=7;r.ledgerNonce=1;v.historicalAccount.committedRegistration=r;v.historicalAccount.executionRegistration=r;v.currentAccount=v.historicalAccount;v.currentAccount.committedHeight=12;v.currentAccount.executionHeight=13;v.currentAccount.ledgerNonce=4;v.blockOriginal={'H','-','P','U','B','L','I','C'};v.successorOriginal={'H','+','1','-','P','U','B','L','I','C'};return v;}
int main(){unsigned count=0;auto test=[&](const char*n,const std::function<void()>&f){f();++count;std::cout<<"PASS "<<n<<"\n";};
test("raw Go policy and two originals remain byte-identical; u64 and independent nonce",[]{auto v=sample();v.currentAccount.ledgerNonce=UINT64_MAX;auto z=w::decodeViewDATA(w::encodeViewDATA(v));ok(z.historicalAccount.policyOriginal==v.historicalAccount.policyOriginal&&z.blockOriginal==v.blockOriginal&&z.successorOriginal==v.successorOriginal);ok(z.currentAccount.ledgerNonce==UINT64_MAX&&z.historicalAccount.ledgerNonce==3&&z.currentAccount.executionRegistration->revision==9007199254740993ULL&&z.currentAccount.executionRegistration->activeFrom==7);});
test("ready frame exact roundtrip and distinct private purpose tag",[]{w::FrameDATA f;f.operation=Operation::Read;f.status=w::Status::OK;f.sequence=3;f.reader[0]=8;f.payload=w::encodeViewDATA(sample());auto b=w::encodeFrameDATA(f);auto z=w::decodeFrameDATA(b);ok(z.reader==f.reader&&z.payload==f.payload);b[0]^=1;denied([&]{w::decodeFrameDATA(b);});});
test("unknown op version and trailing bytes refused",[]{w::FrameDATA f;f.sequence=1;auto b=w::encodeFrameDATA(f);auto x=b;x[sizeof(w::tag)+3]=2;denied([&]{w::decodeFrameDATA(x);});x=b;x[sizeof(w::tag)+7]=9;denied([&]{w::decodeFrameDATA(x);});b.push_back(0);denied([&]{w::decodeFrameDATA(b);});});
test("declared length overflow truncation and overbudget refused before allocation",[]{w::FrameDATA f;f.sequence=1;auto b=w::encodeFrameDATA(f);for(size_t i=b.size()-4;i<b.size();++i)b[i]=255;denied([&]{w::decodeFrameDATA(b);});b.resize(5);denied([&]{w::decodeFrameDATA(b);});Bytes q(w::maxPayloadBytes+1);denied([&]{w::decodeViewDATA(q);});});
test("H currentH originH+1 independent; future or substituted heights rejected",[]{auto v=sample();v.historicalAccount.executionHeight=7;denied([&]{w::encodeViewDATA(v);});v=sample();v.currentCheckpoint.height=10;denied([&]{w::encodeViewDATA(v);});v=sample();v.proof.height=INT64_MAX;denied([&]{w::encodeViewDATA(v);});});
test("wrong pair width and foreign account rejected",[]{auto v=sample();v.currentAccount.executionRegistration->pkB.resize(32);denied([&]{w::encodeViewDATA(v);});v=sample();v.currentAccount.owner="0x2222222222222222222222222222222222222222";denied([&]{w::encodeViewDATA(v);});});
test("partial owner adopted on failed open and original code0 failure preserved",[]{w::SequenceDATA s;w::FrameDATA q;q.sequence=1;s.request(q);auto r=q;r.status=w::Status::Failed;r.reader[0]=7;r.failure={true,0};s.response(w::decodeFrameDATA(w::encodeFrameDATA(r)));ok(s.opened&&s.terminal&&s.reader[0]==7);q.operation=Operation::Read;q.sequence=2;q.reader=r.reader;denied([&]{s.request(q);});q.operation=Operation::Close;s.request(q);auto c=q;c.status=w::Status::Closed;c.failure={true,0};s.response(w::decodeFrameDATA(w::encodeFrameDATA(c)));ok(s.retired);});
test("NotReady same capture allows only explicit later next sequence without reopen",[]{w::SequenceDATA s;w::FrameDATA q;q.sequence=1;s.request(q);auto r=q;r.status=w::Status::OK;r.reader[0]=4;s.response(r);q.operation=Operation::Read;q.reader=r.reader;q.sequence=2;s.request(q);r=q;r.status=w::Status::NotReady;r.failure={true,0};s.response(r);ok(!s.terminal&&s.reader==q.reader);q.sequence=3;s.request(q);denied([&]{s.request(q);});r=q;r.status=w::Status::OK;r.payload=w::encodeViewDATA(sample());s.response(r);q.operation=Operation::Open;q.reader={};q.sequence=4;denied([&]{s.request(q);});});
test("replayed seq and response on wrong reader rejected",[]{w::SequenceDATA s;w::FrameDATA q;q.sequence=1;s.request(q);auto r=q;r.status=w::Status::OK;r.reader[0]=2;s.response(r);denied([&]{s.response(r);});q.operation=Operation::Read;q.reader=r.reader;q.sequence=2;s.request(q);r=q;r.status=w::Status::NotReady;r.failure={true,0};r.reader[0]=3;denied([&]{s.response(r);});});
test("retire cleanup can close with sticky firstcause but never restart read",[]{w::SequenceDATA s;w::FrameDATA q;q.sequence=1;s.request(q);auto r=q;r.status=w::Status::OK;r.reader[0]=3;s.response(r);q.reader=r.reader;q.operation=Operation::Retire;q.sequence=2;s.request(q);r=q;r.status=w::Status::OK;s.response(r);q.operation=Operation::Read;q.sequence=3;denied([&]{s.request(q);});q.operation=Operation::Close;s.request(q);r=q;r.status=w::Status::Closed;r.failure={true,-9};s.response(r);ok(s.retired);});
test("registration owner cannot be borrowed from another account",[]{auto v=sample();v.currentAccount.executionRegistration->owner="0x2222222222222222222222222222222222222222";denied([&]{w::encodeViewDATA(v);});});
std::cout<<"TOTAL "<<count<<" DATA controls; Root=false Source=false Native=false actualLedgerProof=false\n";
}
